class dsl
{
public:
    class area;
    class class_t;
    class dexterity;
    class exp;
    class intelligence;
    class item;
    class level;
    class map;
    class money;
    class point;
    class promotion;
    class role;
    class script;
    class sex;
    class strength;
    class world;

public:
    fb::model::enum_value::DSL header;
    const std::vector<std::any> params;

private:
    static std::vector<std::any> parse_params(const Json::Value& json);

public:
    Json::Value to_json() const;
    dsl(fb::model::enum_value::DSL header, const std::vector<std::any>& params) : header(header), params(params)
    { }
    dsl(const Json::Value& json) : header(build<fb::model::enum_value::DSL>(json["Header"])), params(parse_params(json))
    { }
    dsl(const dsl& other) : header(other.header), params(other.params)
    { }
    dsl(dsl&& other) noexcept : header(other.header), params(std::move(other.params))
    { }
    ~dsl()
    { }
};

class fb::model::dsl::area
{
public:
    const uint16_t left;
    const uint16_t top;
    const uint16_t right;
    const uint16_t bottom;

public:
    area(uint16_t left, uint16_t top, uint16_t right, uint16_t bottom) : 
        left(left),
        top(top),
        right(right),
        bottom(bottom)
    { }
    area(const Json::Value& json) : 
        left(fb::model::build<uint16_t>(json[0])),
        top(fb::model::build<uint16_t>(json[1])),
        right(fb::model::build<uint16_t>(json[2])),
        bottom(fb::model::build<uint16_t>(json[3]))
    { }
    area(const std::vector<std::any>& parameters) : 
        left(any_cast<uint16_t>(parameters[0])),
        top(any_cast<uint16_t>(parameters[1])),
        right(any_cast<uint16_t>(parameters[2])),
        bottom(any_cast<uint16_t>(parameters[3]))
    { }

public:
    fb::model::dsl to_dsl()
    {
        return fb::model::dsl(fb::model::enum_value::DSL::area, {left, top, right, bottom});
    }

    Json::Value to_json() const
    {
        auto json = Json::Value{};
        json["Header"] = fb::model::enum_value::enum_tostring<fb::model::enum_value::DSL>(fb::model::enum_value::DSL::area);
        auto params = Json::Value{Json::arrayValue};
        params.append(left);
        params.append(top);
        params.append(right);
        params.append(bottom);
        json["Params"] = params;
        return json;
    }
};


